'use strict';

const communities=[{id:'friends',name:'프렌즈 플레이룸',image:'assets/kakao/friends.png',desc:'같이 만들고, 같이 놀아요.'},{id:'solo',name:'나 혼자만 레벨업',image:'assets/official/solo-leveling.jpg',desc:'헌터들의 창작과 이야기'},{id:'korean',name:'한국어 같이 배워요',image:'assets/kiwi/tea.png',desc:'하루 한마디, 함께 연습해요.'}];
communities.unshift({id:'squid',name:'오징어 게임 · Global Lobby',image:'assets/official/squid-game.jpg',desc:'20명의 참가자가 게임을 기다리고 있어요.'});
let community='friends', channel='general', communityOpen=false;
let channelData={};try{channelData=JSON.parse(localStorage.getItem('kakao-one-channels')||'{}')||{};}catch(_){}
for(const c of communities){if(!channelData[c.id]||!Array.isArray(channelData[c.id].channels))channelData[c.id]={channels:[{id:'notice',name:'공지',category:'안내'},{id:'general',name:'자유대화',category:'라운지'},{id:'creations',name:'작품공유',category:'라운지'},{id:'korean',name:'한국어 연습',category:'라운지'}],messages:[]};}
const squidPlayers=[
 ['Alex','🇺🇸','미국','Ready for the first game!'],['Emma','🇬🇧','영국','Hi everyone! 안녕하세요 👋'],['Lucas','🇫🇷','프랑스','Bonjour! Let’s play together.'],['Sofia','🇪🇸','스페인','Hola! I love Squid Game.'],['Luca','🇮🇹','이탈리아','Ciao! Teamwork first?'],['Mia','🇩🇪','독일','Hello from Berlin!'],['Oliver','🇦🇺','호주','Good luck, everyone!'],['Chloe','🇨🇦','캐나다','I’m ready. Let’s go!'],['Yuki','🇯🇵','일본','안녕하세요! 같이 놀아요.'],['Hana','🇯🇵','일본','First time playing here 😊'],['Wei','🇸🇬','싱가포르','Hello from Singapore!'],['Mei','🇹🇼','대만','Can we practice Korean too?'],['Arjun','🇮🇳','인도','Let’s make it to the finish line!'],['Priya','🇮🇳','인도','무궁화 꽃이 피었습니다!'],['Nina','🇧🇷','브라질','Oi! Who’s on my team?'],['Diego','🇲🇽','멕시코','Ready when you are!'],['Linh','🇻🇳','베트남','안녕하세요. 반가워요!'],['Pim','🇹🇭','태국','Hello! This looks fun.'],['Aisha','🇲🇾','말레이시아','Let’s help each other!'],['Noah','🇳🇿','뉴질랜드','Twenty players. One lobby. Let’s go!']
].map(([name,flag,country,greeting],i)=>({id:'sg-'+i,name,flag,country,greeting,number:String(i+1).padStart(3,'0'),avatar:'assets/kakao/profile-'+(i%3+1)+'.png'}));
if(!channelData.squid.seedVersion){
 channelData.squid.channels=[{id:'notice',name:'게임 안내',category:'안내'},{id:'general',name:'대기실',category:'라운지'},{id:'game',name:'게임 진행',category:'라운지'}];
 channelData.squid.messages.unshift(...squidPlayers.map((p,i)=>({id:'welcome-'+p.id,author:p.id,channel:'general',text:p.greeting,at:Date.UTC(2026,10,6,4,0+i)})));
 channelData.squid.seedVersion=1;saveChannels();
}
let squidStage=0;
function squidMemberList(){openModal('참가자 21명',`<p class="small-note">가상 외국인 참가자 20명 · 나 1명</p><div class="squid-member-list">${squidPlayers.map(p=>`<div><img src="${p.avatar}" alt=""><span><strong>${p.flag} ${p.name}</strong><small>${p.country} · ${p.number}번</small></span><i>대기</i></div>`).join('')}<div><img src="assets/kakao/profile-1.png" alt=""><span><strong>🇺🇸 Alex Morgan · You</strong><small>USA · 021</small></span></div></div>`);}
const kiwiAsset=name=>`<img src="assets/kiwi/components/${name}.svg" alt="" aria-hidden="true">`;
function squidMessage(m){const p=squidPlayers.find(p=>p.id===m.author);return `<div class="kiwi-message ${p?'':'kiwi-me'}">${p?`<img class="kiwi-avatar" src="${p.avatar}" alt="">`:''}<div class="kiwi-message-content">${p?`<strong class="kiwi-author">${esc(p.name)}</strong>`:''}<div class="kiwi-message-line"><p class="kiwi-bubble">${esc(m.text)}</p><time>${new Date(m.at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',hour12:false})}</time></div></div></div>`;}
function renderSquidRoom(){const db=channelData.squid;const ch=db.channels.find(c=>c.id===channel)||db.channels[1];channel=ch.id;
 const info=channel==='game'?'초록불에는 이동하고 빨간불에는 멈추세요.':channel==='notice'?'외국인 참가자 20명과 함께하는 시연용 게임방입니다.':'외국인 참가자 20명이 입장했습니다.';
 return `<div class="kiwi-chat"><header class="kiwi-header"><button class="kiwi-icon-button" data-action="community-back" aria-label="오픈채팅 목록">${kiwiAsset('back')}</button><img class="kiwi-room-image" src="assets/official/squid-game.jpg" alt=""><div class="kiwi-room-info"><h2>오징어 게임</h2><button data-action="squid-members">21명 <span>· ${esc(ch.name)}</span></button></div><button class="kiwi-icon-button" data-action="kiwi-room-menu" aria-label="채널과 참가자 메뉴">${kiwiAsset('menu')}</button></header><button class="kiwi-notice" data-action="${channel==='game'?'squid-start':'kiwi-room-menu'}">${kiwiAsset('notice')}<span>${channel==='game'?'무궁화 꽃이 피었습니다 · 게임 시작':'# '+esc(ch.name)}</span><span class="kiwi-notice-arrow">›</span></button><div class="kiwi-messages" id="channel-messages"><div class="kiwi-date">2026년 11월 6일</div><div class="kiwi-system">${info}</div>${db.messages.filter(m=>m.channel===channel).map(squidMessage).join('')}</div><form id="channel-form" class="kiwi-compose"><label class="sr-only" for="channel-input">채널 메시지</label><div class="kiwi-input"><input id="channel-input" name="message" maxlength="1000" placeholder="${esc(ch.name)}에 메시지 보내기..." required autocomplete="off"><button class="kiwi-icon-button" type="button" data-action="kiwi-room-menu" aria-label="채널 메뉴">${kiwiAsset('add-line')}</button></div><button class="kiwi-send" type="submit" aria-label="전송">${kiwiAsset('send')}</button></form></div>`;
}
function kiwiRoomMenu(){openModal('오징어 게임',`<div class="kiwi-menu"><h3>채널</h3>${channelData.squid.channels.map(c=>`<button class="${channel===c.id?'selected':''}" data-action="kiwi-select-channel" data-id="${c.id}"># ${esc(c.name)}</button>`).join('')}<h3>참가자</h3><button data-action="squid-members">참가자 21명 보기</button></div>`);}
function renderSquidGame(){const done=squidStage>=6,red=squidStage%2===1;openModal('무궁화 꽃이 피었습니다',`<div class="squid-round ${red?'red':'green'}"><span class="squid-round-symbol">${done?'○ △ □':red?'□':'○'}</span><small>${done?'FINISH':'ROUND '+(Math.floor(squidStage/2)+1)+' / 3'}</small><h3>${done?'완주했습니다!':red?'빨간불, 멈추세요!':'초록불, 앞으로!'}</h3><p>${done?'가상 참가자들과 첫 게임을 마쳤습니다.':'불빛에 맞는 행동을 선택하세요.'}</p>${done?button('대기실로','squid-finish','','primary'):`<div class="button-row">${button('이동하기','squid-move','','primary')}${button('멈추기','squid-stop')}</div>`}</div>`);}
function saveChannels(){try{localStorage.setItem('kakao-one-channels',JSON.stringify(channelData));}catch(_){toast('기기 저장 공간을 확인해 주세요.');}}
let openchatTab='mine';
function renderOpenchatEntry(){
 const matching=communities.filter(c=>matchText(c.name+' '+c.desc));
 const rooms=openchatTab==='korean'?matching.filter(c=>c.id==='korean'):openchatTab==='popular'?[...matching].reverse():matching;
 return `<div class="native-openchat"><button class="native-open-search" data-action="openchat-search">${icon('search')}<span>${searchQuery?esc(searchQuery):'관심 키워드로 오픈채팅 검색'}</span></button><div class="native-open-tabs" aria-label="오픈채팅 분류">${[['mine','💬 내 채팅방'],['popular','🔥 지금 뜨는'],['korean','# 한국어']].map(([id,name])=>`<button data-action="openchat-tab" data-id="${id}" class="${openchatTab===id?'selected':''}" aria-pressed="${openchatTab===id}">${name}</button>`).join('')}</div><div class="native-open-rooms">${rooms.map(c=>{const messages=channelData[c.id].messages||[],last=messages[messages.length-1];return `<button class="native-open-row" data-action="community" data-id="${c.id}"><img class="native-open-avatar" src="${c.image}" alt=""><span class="native-open-copy"><strong>${icon('rooms')}<span>${c.name}</span></strong><span class="native-open-preview">${last?esc(last.text||'이모티콘'):esc(c.desc)}</span></span><span class="native-open-meta">${last?new Date(last.at).toLocaleTimeString('ko-KR',{hour:'numeric',minute:'2-digit'}):'체험'}</span></button>`;}).join('')||empty('검색 결과가 없습니다.')}</div><div class="native-open-profile"><h2>나의 오픈채팅 Lite <span>1</span></h2><button class="native-open-row" data-action="community" data-id="korean"><img class="native-open-avatar" src="assets/kiwi/tea.png" alt=""><span class="native-open-copy"><strong>한국어 같이 배워요</strong><span class="native-open-preview">하루 한마디, 함께 연습해요.</span></span>${icon('arrow')}</button></div></div>`;
}
function renderOpenchat(){
 if(!communityOpen)return renderOpenchatEntry();
 if(community==='squid')return renderSquidRoom();
 const c=communities.find(c=>c.id===community), db=channelData[community], ch=db.channels.find(c=>c.id===channel)||db.channels[0];channel=ch.id;
 const seed=channel==='notice'?'환영합니다! 관심 있는 채널에서 이야기를 시작해 보세요.':channel==='creations'?'직접 만든 프렌즈 게임이나 이야기를 소개해 주세요.':channel==='korean'?'오늘의 표현은 “같이 가요”예요. 함께 연습해 볼까요?':'반가워요! 오늘은 어떤 이야기를 나눠볼까요?';
 return `<div class="channel-app"><div class="community-heading"><button class="icon-button" data-action="community-back" aria-label="커뮤니티 목록">${icon('back')}</button><img src="${c.image}" alt=""><strong>${c.name}</strong><span>체험</span></div><div class="channel-layout"><aside class="channel-sidebar"><div class="channel-heading">채널<button class="icon-button" data-action="add-channel" aria-label="채널 추가">${icon('plus')}</button></div>${['안내','라운지'].map(cat=>`<p class="channel-category">${cat}</p>${db.channels.filter(ch=>ch.category===cat).map(ch=>`<button class="channel-link ${channel===ch.id?'active':''}" data-action="channel" data-id="${ch.id}" ${channel===ch.id?'aria-current="page"':''}><span>#</span> ${esc(ch.name)}</button>`).join('')}`).join('')}<div class="channel-me"><img src="assets/kakao/profile-1.png" alt=""> Alex Morgan</div></aside><section class="channel-conversation"><div class="channel-title"><span>#</span> ${esc(ch.name)}</div><div class="channel-messages" id="channel-messages"><div class="channel-welcome"><span>#</span><h3>${esc(ch.name)}</h3><p>이 채널의 시작입니다.</p></div><div class="channel-message"><img src="assets/kakao/apeach-profile.png" alt=""><div><strong>채널 가이드 <small>안내</small></strong><p>${seed}</p></div></div>${db.messages.filter(m=>m.channel===channel).map(m=>`<div class="channel-message"><img src="assets/kakao/profile-1.png" alt=""><div><strong>Alex Morgan <small>${new Date(m.at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})}</small></strong>${m.card?studioCardMessage(m.card,'open:'+community):`<p>${esc(m.text)}</p>`}</div></div>`).join('')}</div><form id="channel-form" class="channel-compose"><label class="sr-only" for="channel-input">채널 메시지</label><input id="channel-input" name="message" maxlength="1000" placeholder="#${esc(ch.name)}에 메시지 보내기" required autocomplete="off"><button type="submit" aria-label="전송">${icon('send')}</button></form></section></div></div>`;
}

document.addEventListener('click',event=>{
 const el=event.target.closest('[data-action]');if(!el)return;
 if(el.dataset.action==='kiwi-room-menu')kiwiRoomMenu();
 if(el.dataset.action==='kiwi-select-channel'){channel=el.dataset.id;closeModal();render();}
});
